// Monta a entrada da seção 4.2 a partir do gatilho da Meta (saída simplificada) e da consulta da campanha na Graph API.
// O gatilho não traz a campanha nem a plataforma. Se a consulta falhar, o lead entra sem elas, e o fluxo avisa o admin no fim.
const gatilho = $('Novo lead da Meta').item.json;
const consulta = $json.error ? {} : $json;
const dados = gatilho.data || {};
function texto(valor) {
  if (valor === undefined || valor === null || typeof valor === 'object') return null;
  const limpo = String(valor).trim();
  return limpo ? limpo : null;
}
function referencia(objeto) {
  return objeto && texto(objeto.id) ? { id: texto(objeto.id), nome: texto(objeto.name) } : null;
}
// A Meta manda a data como 2026-10-14T17:45:12+0000; o CRM espera ISO 8601 com o fuso no formato +00:00.
function quando(valor) {
  const data = new Date(String(valor || '').replace(/([+-][0-9]{2})([0-9]{2})$/, '$1:$2'));
  return isNaN(data.getTime()) ? $now.toUTC().toISO() : data.toISOString();
}

// Os mesmos campos que a importação reconhece no CSV da Meta; os outros vão para as respostas extras.
const conhecidos = ['full_name', 'first_name', 'last_name', 'email', 'work_email', 'phone_number', 'work_phone_number', 'cpf', 'cnpj', 'cpf_cnpj', 'state', 'province', 'estado', 'uf', 'company_name', 'empresa'];
const respostasExtras = {};
for (const campo of Object.keys(dados)) {
  if (!conhecidos.includes(campo) && texto(dados[campo])) respostasExtras[campo] = texto(dados[campo]);
}
const nome = texto(dados.full_name) || [texto(dados.first_name), texto(dados.last_name)].filter(Boolean).join(' ') || null;
// Os leads da Ferramenta de Teste de Anúncios de Cadastro chegam com os valores "<test lead: dummy data for ...>".
const teste = Object.values(dados).some(function (valor) { return typeof valor === 'string' && valor.indexOf('<test lead') === 0; });
const plataformas = { fb: 'facebook', ig: 'instagram', facebook: 'facebook', instagram: 'instagram' };

return {
  json: {
    campanhaFaltou: Boolean($json.error),
    lead: {
      origem: 'meta_lead_ads',
      idExterno: texto(gatilho.id),
      recebidoEm: quando(gatilho.created_time),
      teste: teste,
      nome: nome,
      email: texto(dados.email) || texto(dados.work_email),
      telefone: texto(dados.phone_number) || texto(dados.work_phone_number),
      cpfCnpj: texto(dados.cpf) || texto(dados.cnpj) || texto(dados.cpf_cnpj),
      uf: texto(dados.state) || texto(dados.province) || texto(dados.estado) || texto(dados.uf),
      empresa: texto(dados.company_name) || texto(dados.empresa),
      plataforma: plataformas[String(consulta.platform || '').toLowerCase()] || null,
      campanha: texto(consulta.campaign_id) ? { id: texto(consulta.campaign_id), nome: texto(consulta.campaign_name) } : null,
      conjunto: referencia(gatilho.adset),
      anuncio: referencia(gatilho.ad),
      formulario: referencia(gatilho.form),
      respostasExtras: Object.keys(respostasExtras).length ? respostasExtras : null,
    },
  },
};

// Classifica a falha do envio ao CRM (seção 4.5). Guarda só o código ou o tipo da falha, nunca o corpo da resposta, que pode ter dados pessoais.
const erro = $json.error || {};
const mensagem = String(erro.message || '');
const prefixo = /^([0-9]{3}) - /.exec(mensagem);
const codigo = String(erro.httpCode || erro.status || erro.statusCode || (prefixo ? prefixo[1] : ''));

let ultimoErro;
if (/^[0-9]{3}$/.test(codigo)) {
  ultimoErro = 'HTTP ' + codigo;
} else if (/timeout|timed out|ETIMEDOUT|ECONNABORTED/i.test(String(erro.code || '') + ' ' + mensagem)) {
  ultimoErro = 'Tempo esgotado (10 s)';
} else {
  ultimoErro = 'Falha de conexão';
}

// Um 4xx que não é 408 nem 429 é definitivo: tentar de novo não resolve, e o admin precisa olhar.
const definitiva = /^4[0-9]{2}$/.test(codigo) && codigo !== '408' && codigo !== '429';
return { json: { definitiva: definitiva, ultimoErro: ultimoErro, lead: $('Montar o lead').item.json.lead } };
